import { test } from 'node:test';
import assert from 'node:assert';
import { readFileSync } from 'node:fs';
import { hash32, hash128, hash128x64 } from '../src/index.ts';

// Generated by scripts/gen-vectors.py from Python mmh3; never regenerate from this package.
interface Vector {
  kind: 'bytes' | 'ascii' | 'str';
  s: string | null;
  b: string;
  seed: number;
  h32: number;
  x86: string;
  x64: string;
}

const vectors: Vector[] = JSON.parse(
  readFileSync(new URL('./vectors.json', import.meta.url), 'utf8')
);

function fromHex(hex: string): Uint8Array {
  return Uint8Array.from(hex.match(/../g) ?? [], (h) => parseInt(h, 16));
}

test('vectors: fixture is loaded', () => {
  assert.strictEqual(vectors.length, 468);
});

for (const v of vectors) {
  // Hash the string itself when there is one, so a wrong string encoding cannot pass.
  const inputs: Array<[string, string | Uint8Array]> = [['bytes', fromHex(v.b)]];
  if (v.s !== null) inputs.unshift(['string', v.s]);

  for (const [label, input] of inputs) {
    const name = `${v.kind} len=${v.b.length / 2} seed=${v.seed} ${label}${
      v.s !== null && v.s.length <= 16 ? ` ${JSON.stringify(v.s)}` : ''
    }`;
    test(`vectors: ${name}`, () => {
      assert.strictEqual(hash32(input, v.seed), v.h32, 'hash32');
      assert.strictEqual(hash128(input, { seed: v.seed }), v.x86, 'hash128');
      assert.strictEqual(hash128x64(input, { seed: v.seed }), v.x64, 'hash128x64');
    });
  }
}
